import { render, screen } from '@testing-library/react';
import ChangelogPage from '@/app/changelog/page';

jest.mock('@/data/changelog.json', () => ([
  { title: 'Recent', description: 'r', date: '2026-08-29T00:00:00Z' },
]));

describe('ChangelogPage — DTS-04 date formatting', () => {
  it('renders absolute dates as DD MMM YYYY', async () => {
    const ui = await ChangelogPage();
    render(ui);
    // 2026-08-29 must render as '29 Aug 2026' somewhere on the page.
    expect(screen.getByText(/29 Aug 2026/)).toBeInTheDocument();
  });
});
